import sys
from collections import deque

s = sys.stdin.read().split()[0]
n = len(s)
start = int(s, 2)
full = (1 << n) - 1

def works(K):
    masks = []
    for l in range(n):
        for r in range(l + K - 1, n):
            masks.append(((1 << (r - l + 1)) - 1) << l)
    seen = {start}
    dq = deque([start])
    while dq:
        x = dq.popleft()
        if x == 0 or x == full:
            return True
        for m in masks:
            y = x ^ m
            if y not in seen:
                seen.add(y)
                dq.append(y)
    return False

for K in range(n, 0, -1):
    if works(K):
        print(K)
        break

